<body class="min-h-screen bg-[#F5F7FB] font-sans text-slate-600 antialiased">
    <header class="relative z-20 bg-white border-b border-slate-100">
        <div class="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8 py-4 flex items-center justify-between">
            <a href="../index.html" class="inline-flex items-center">
                                    <img src="../images/J3vnilG6TddFEwFkWebd0LvUcwomzTgY4EFhaEDN.png" alt="Express Cargo" class="h-10 w-auto">
                            </a>
            <div class="flex items-center gap-2 sm:gap-3">
                <a href="../order.html" class="hidden sm:inline-flex items-center rounded-xl border-2 border-primary-600 text-primary-600 hover:bg-[#E8F1FB] px-4 py-2 text-sm font-semibold transition-colors">
                    Track
                </a>
                <a href="../contact.html" class="inline-flex items-center rounded-xl bg-secondary-600 hover:bg-secondary-700 text-white px-4 sm:px-5 py-2.5 text-sm font-semibold transition-colors">
                    Contact Us
                </a>
            </div>
        </div>
    </header>

    <section class="relative overflow-hidden bg-[#0B1F3A] text-white pt-16 sm:pt-20 pb-28 sm:pb-32">
        <div class="pointer-events-none absolute inset-0 opacity-20" style="background-image: radial-gradient(rgba(255,255,255,0.14) 1px, transparent 1px); background-size: 22px 22px;"></div>
        <div class="pointer-events-none absolute -top-24 -right-16 h-72 w-72 rounded-full bg-secondary-500/15 blur-3xl"></div>
        <div class="pointer-events-none absolute -bottom-20 -left-16 h-64 w-64 rounded-full bg-white/5 blur-3xl"></div>

        <div class="relative z-10 mx-auto max-w-3xl px-4 sm:px-6 lg:px-8 text-center">
            <div class="inline-flex items-center gap-2 rounded-full bg-white/10 px-3.5 py-1.5 text-xs font-bold tracking-wider text-white/90 mb-5 ring-1 ring-white/15">
                <span class="h-1.5 w-1.5 rounded-full bg-secondary-500"></span>
                Error 404
            </div>
            <p class="font-display text-7xl sm:text-8xl font-extrabold leading-none tracking-tight text-white/15 select-none" aria-hidden="true">
                404
            </p>
            <h1 class="mt-2 font-display text-3xl sm:text-4xl lg:text-[2.75rem] font-extrabold leading-tight text-white">
                Page not found
            </h1>
            <div class="mx-auto mt-5 h-1.5 w-16 rounded-full bg-secondary-500"></div>
        </div>
    </section>

    <main class="relative z-10 -mt-16 sm:-mt-20 px-4 sm:px-6 lg:px-8 pb-16">
        <div class="mx-auto w-full max-w-xl rounded-[1.75rem] border border-slate-100 bg-white px-6 py-10 sm:px-10 sm:py-12 text-center" style="box-shadow: 0 18px 44px rgba(11,31,58,0.10);">
            <div class="mx-auto mb-5 inline-flex h-14 w-14 items-center justify-center rounded-2xl bg-[#E8F1FB] text-primary-600">
                                        <i class="fas fa-map-location-dot text-xl"></i>
                            </div>

            <p class="mx-auto max-w-md text-base sm:text-lg text-slate-500 leading-relaxed">
                The page you are looking for is not here. It may have been moved, or the link may be out of date.            </p>

            <div class="mt-8 flex flex-col sm:flex-row items-center justify-center gap-3">
                                    <a href="../index.html" class="inline-flex w-full sm:w-auto items-center justify-center gap-2 rounded-xl bg-primary-600 hover:bg-primary-700 text-white font-semibold px-6 py-3.5 transition-colors">
                        Back to home
                        <i class="fas fa-arrow-right text-sm"></i>
                    </a>
                    <a href="../order.html" class="inline-flex w-full sm:w-auto items-center justify-center gap-2 rounded-xl border-2 border-primary-600 text-primary-600 hover:bg-[#E8F1FB] font-semibold px-6 py-3.5 transition-colors">
                        <i class="fas fa-search-location text-sm"></i>
                        Track a parcel
                    </a>
                            </div>
        </div>
    </main>

    <footer class="mt-auto px-4 sm:px-6 lg:px-8 py-8">
        <p class="text-center text-sm text-slate-400">
            © 2026 Express Cargo. All rights reserved.
        </p>
    </footer>


</body></html>